form.script:
(function () {
    // Restore active tab from sessionStorage
    var savedTab = sessionStorage.getItem('profileActiveTab');
    if (savedTab) {
        sessionStorage.removeItem('profileActiveTab');
        var tabEl = document.querySelector('[data-bs-target="' + savedTab + '"]');
        if (tabEl) {
            new bootstrap.Tab(tabEl).show();
        }
    }

    // Update URL hash on tab switch
    document.querySelectorAll('#profileTabs button[data-bs-toggle="tab"]').forEach(function (btn) {
        btn.addEventListener('shown.bs.tab', function (e) {
            history.replaceState(null, null, e.target.dataset.bsTarget);
        });
    });

    // Toggle work history form
    var toggleBtn = document.getElementById('btn-toggle-wh-form');
    var whFormSection = document.getElementById('wh-form-section');
    var cancelBtn = document.getElementById('btn-cancel-wh-form');
    function setWhInputs(enabled) {
        whFormSection.querySelectorAll('input').forEach(function (inp) {
            inp.disabled = !enabled;
        });
    }
    if (toggleBtn && whFormSection) {
        setWhInputs(false);
        toggleBtn.addEventListener('click', function () {
            whFormSection.classList.remove('d-none');
            toggleBtn.classList.add('d-none');
            setWhInputs(true);
        });
        whFormSection.addEventListener('keydown', function (e) {
            if (e.key === 'Enter') { e.preventDefault(); }
        });
    }
    if (cancelBtn && whFormSection && toggleBtn) {
        cancelBtn.addEventListener('click', function () {
            whFormSection.classList.add('d-none');
            toggleBtn.classList.remove('d-none');
            whFormSection.querySelectorAll('input').forEach(function (inp) { inp.value = ''; });
            setWhInputs(false);
        });
    }

    // Preserve tab on work history add
    var addBtn = document.querySelector('[name="add_work_history"]');
    if (addBtn) {
        addBtn.addEventListener('click', function () {
            sessionStorage.setItem('profileActiveTab', '#tab-work');
        });
    }

    // Cross-tab validation: switch to tab with first invalid field
    document.querySelectorAll('form[action="/my/profile"] [required]').forEach(function (field) {
        field.addEventListener('invalid', function () {
            var pane = this.closest('.tab-pane');
            if (pane && !pane.classList.contains('active')) {
                var tabBtn = document.querySelector('[data-bs-target="#' + pane.id + '"]');
                if (tabBtn) {
                    new bootstrap.Tab(tabBtn).show();
                }
            }
        });
    });

    // Also restore from URL hash on first load
    var hash = window.location.hash;
    if (hash && !savedTab) {
        var hashTabEl = document.querySelector('[data-bs-target="' + hash + '"]');
        if (hashTabEl) {
            new bootstrap.Tab(hashTabEl).show();
        }
    }
})();
